. The factorial of a non-negative integer n, denoted by n!, is the product of all positive integers less than or equal to n.

```javascript
function factorial(n) {
    if (n < 0) {
        return "Error: Factorial is not defined for negative numbers";
    } else if (n === 0 || n === 1) {
        return 1;
    } else {
        let result = 1;
        for (let i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}

